const form = $('Audit a landing page').first().json
const brand = $('Get the brand kit').first().json
const tokens = $('Get the design tokens').first().json
const hero = $('Read the hero and sections').first().json

// WCAG 2 contrast ratio between two hex colors.
const hex = h => { h = String(h || '').replace('#', ''); if (h.length === 3) h = h.split('').map(c => c + c).join(''); return /^[0-9a-f]{6}$/i.test(h) ? h : null }
const lum = h => { const v = [0, 2, 4].map(i => parseInt(h.slice(i, i + 2), 16) / 255).map(c => c <= 0.03928 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4); return 0.2126 * v[0] + 0.7152 * v[1] + 0.0722 * v[2] }
const contrast = (a, b) => { a = hex(a); b = hex(b); if (!a || !b) return null; const [x, y] = [lum(a), lum(b)].sort((m, n) => n - m); return Math.round(((x + 0.05) / (y + 0.05)) * 100) / 100 }
const grade = r => r == null ? 'unknown' : r >= 7 ? 'AAA' : r >= 4.5 ? 'AA' : r >= 3 ? 'AA large text only' : 'fails'

const c = brand.colors || {}
const pairs = [
  ['body text on background', c.text, c.background],
  ['primary color on background', c.primary, c.background],
  ['white text on a primary button', '#ffffff', c.primary],
  ['accent on background', c.accent, c.background],
].filter(([, a, b]) => a && b).map(([what, a, b]) => { const r = contrast(a, b); return { what, colors: a + ' on ' + b, ratio: r, wcag: grade(r) } })

// Design-system size. The stylesheet holds every value the site ships
// (responsive, hover, unused), so "core" = values used at least 5 times.
const list = v => Array.isArray(v) ? v : []
const core = v => list(v).filter(x => (x.count || 0) >= 5).length
// Solid colors only: no transparent, rgba/hsla or alpha hex (#rgba, #rrggbbaa).
const solid = list(tokens.colors).filter(x => { const v = String(x.color || ''); return !/transparent|inherit|currentcolor|rgba|hsla|\/\s*[\d.]+%?\s*\)/i.test(v) && !/^#([0-9a-f]{4}|[0-9a-f]{8})$/i.test(v) })
const counts = {
  fontFamilies: (brand.fonts || []).length,
  fontFamilyNames: brand.fonts || [],
  fontSizes: { total: list(tokens.fontSizes).length, usedOften: core(tokens.fontSizes), mostUsed: list(tokens.fontSizes).slice(0, 8).map(x => x.size) },
  fontWeights: list(tokens.fontWeights).length,
  colors: { total: solid.length, usedOften: core(solid), mostUsed: solid.slice(0, 8).map(x => x.color) },
  spacingValues: { total: list(tokens.spacing).length, usedOften: core(tokens.spacing) },
  cornerRadii: { total: list(tokens.borderRadiuses).length, usedOften: core(tokens.borderRadiuses) },
  shadows: list(tokens.boxShadows).length,
  note: 'Counts come from the whole stylesheet (responsive and hover states included); "usedOften" (5+ uses) is the real design system.',
}

// The hero's words: headline and calls to action, read from its code.
const code = String(hero.code || '')
const textOf = s => s.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim()
// Responsive sites repeat the headline per breakpoint: keep one copy.
const once = t => { const w = t.split(' '); for (let n = 4; n >= 2; n--) { if (w.length % n) continue; const k = w.length / n, c = w.slice(0, k).join(' '); if (Array.from({ length: n }, (_, i) => w.slice(i * k, (i + 1) * k).join(' ')).every(x => x === c)) return c } return t }
const headline = once(textOf((code.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i) || code.match(/<h2[^>]*>([\s\S]*?)<\/h2>/i) || [, ''])[1]))
// Animated word rotators ("for ChatGPT / Claude / Cursor") keep every option in
// the HTML at once, so a repeated word usually means rotating text, not a run-on.
const words = headline.toLowerCase().match(/[a-z][a-z0-9.-]{3,}/g) || []
const headlineNote = words.length !== new Set(words).size
  ? 'The headline repeats words: it is probably an animated word rotator, where visitors see one option at a time. Judge the base sentence, not the repetition.'
  : ''
// Calls to action: buttons and action-worded links first (product screenshots
// inside a hero are full of menu labels, which are not CTAs).
const verb = /^(get|start|try|sign|book|buy|shop|join|request|contact|download|see|learn|watch|create|explore|talk|schedule|order|subscribe|open|claim|discover|apply|install|view)\b/i
const links = [...code.matchAll(/<(a|button)\b([^>]*)>([\s\S]*?)<\/\1>/gi)].map(m => ({ text: textOf(m[3]), button: m[1].toLowerCase() === 'button' || /btn|button|cta/i.test(m[2]) }))
  .filter(l => l.text && l.text.length < 40)
// Action-worded links/buttons are CTAs; other buttons are listed apart (often
// menu labels inside a product screenshot).
const ctas = links.filter(l => verb.test(l.text)).map(l => l.text)
const otherButtons = links.filter(l => l.button && !verb.test(l.text)).map(l => l.text)
const sections = (hero.sections || []).sort((a, b) => a.order - b.order).map(s => String(s.label || '').slice(0, 80))

const facts = {
  website: form['Landing page URL'],
  brand: { colors: c, fonts: brand.fonts || [], logoFound: !!brand.logo, colorsDeclaredOrInferred: brand.signals?.explanation || '' },
  contrast: pairs,
  designSystem: counts,
  hero: {
    headline,
    headlineNote,
    callsToAction: [...new Set(ctas)].slice(0, 5),
    note: ctas.length ? '' : 'No action-worded call to action (Get started, Try, Sign up, Book...) found in the hero.',
    otherButtonsInHero: [...new Set(otherButtons)].slice(0, 5),
  },
  sectionsInOrder: sections,
  goal: form['What should this page get visitors to do?'] || 'not given',
}
return [{ json: { facts, factsText: JSON.stringify(facts, null, 2) } }]
